SELECT * FROM NPSBATCH 


        AND NPSBATCH_FILE_ID = #{fileid,jdbcType=CHAR}


        AND NPSBATCH_FILE_ID != '' AND NPSBATCH_FILE_ID IS NOT NULL 


        AND NPSBATCH_TX_DATE = #{txdate,jdbcType=CHAR}


ORDER BY NPSBATCH_BATCH_NO

SELECT * FROM NPSBATCH


        AND NPSBATCH_TX_DATE = #{txdate,jdbcType=CHAR}


        AND NPSBATCH_BATCH_NO = #{BatchNo,jdbcType=CHAR}


ORDER BY NPSBATCH_BATCH_NO

SELECT * FROM NPSBATCH


        AND NPSBATCH_FILE_ID = #{fileid,jdbcType=CHAR}


        AND NPSBATCH_BATCH_NO = #{BatchNo,jdbcType=CHAR}


        AND NPSBATCH_TX_DATE = #{txdate,jdbcType=CHAR}


ORDER BY NPSBATCH_BATCH_NO

SELECT * FROM NPSBATCH
INNER JOIN NPSDTL
ON NPSDTL.NPSDTL_BAT_NO = NPSBATCH.NPSBATCH_BATCH_NO
WHERE NPSBATCH.NPSBATCH_FILE_ID = #{filename, jdbcType=CHAR}
AND NPSBATCH.NPSBATCH_TX_DATE = #{txDate, jdbcType=CHAR}
AND NPSBATCH.NPSBATCH_BATCH_NO = #{batchNo, jdbcType=CHAR}

SELECT * FROM NPSBATCH
WHERE NPSBATCH_FILE_ID = #{filename, jdbcType=CHAR}
AND NPSBATCH_TX_DATE = #{txDate, jdbcType=CHAR}
AND NPSBATCH_BATCH_NO = #{batchNo, jdbcType=CHAR}
AND NPSBATCH_BRANCH = #{branch, jdbcType=CHAR}
AND NPSBATCH_RESULT IS NULL

SELECT * FROM NPSBATCH



            NPSBATCH_TX_DATE = #{W_DATE,jdbcType=CHAR}
            AND NPSBATCH_RESULT = '00'


            NPSBATCH_FILE_ID = #{W_FILENAME,jdbcType=CHAR}
